const systemActivity: TypeSchema = {
  id: "system.activity",
  label: "Activity",
  description: "User-meaningful telemetry emitted by an external-service connector at semantic boundaries — sync runs, errors, things that need user attention. Severity drives surfacing: `info` is routine, `warning` is operational, `error` is recoverable failure, `action_required` is surfaced as a Repairs-style inbox (the user has to do something — re-authorize, resolve a tombstone conflict, etc.). Per-Connection feed-eligibility lives on the emitting `system.connection.feed_activity`; when true, server stamps tier:'feed' on activity items the connector writes. Lifecycle bounded to active | revoked. Has no tier by default.",
  version: 1,
  fields: {
    connection_id: { type: "string", description: "Id of the emitting system.connection item", required: true },
    severity: { type: "enum", description: "Surfacing level. `info` for routine completion, `warning` for non-blocking concerns, `error` for recoverable failure, `action_required` for items the user has to resolve (surfaced via /items?type=system.activity&filter=properties.severity eq \"action_required\")", required: true, enum_values: ["info", "warning", "error", "action_required"] },
    summary: { type: "string", description: "Short one-liner shown in feed surfaces", required: true },
    detail: { type: "object", description: "Optional JSON context for richer rendering or programmatic resolution" },
  },
};

const systemApp: TypeSchema = {
  id: "system.app",
  label: "App",
  description: "A registered app identity. Carries the human-readable identity (display name, homepage) for an app whose types live under `app.<name>.<type>`. The wire layer does not require a `system.app` record to exist when a type under `app.<name>.*` registers — these records are advisory metadata for surfacing in connected-apps UIs, not registration prerequisites. Has no tier and no lifecycle status; the row's existence is the activation signal.",
  version: 1,
  fields: {
    name: { type: "string", description: "Stable identifier slug used in app.<name>.<type> registrations", required: true },
    display_name: { type: "string", description: "Human-readable display name" },
    homepage_url: { type: "url", description: "App marketing/landing page" },
    publisher_handle: { type: "string", description: "Optional reference to the publishing entity's handle" },
  },
};

const systemConnection: TypeSchema = {
  id: "system.connection",
  label: "Connection",
  description: "An approved relationship between this Marfa tenant and an external authority. `kind` discriminates between variants: `app` (an OAuth client this user has authorized) and `integration` (a connected upstream service such as Google Calendar). Lifecycle bounded to active | revoked. Has no tier. The integration kind also carries a `runtime_status` distinct from the lifecycle `status`; runtime_status is server-stamped only (the runtime executor is the legitimate writer).",
  version: 1,
  fields: {
    kind: { type: "enum", description: "Discriminator for connection variant", required: true, enum_values: ["app", "integration"] },
    client_id: { type: "string", description: "OAuth client identifier (for kind: app)" },
    scopes: { type: "array", description: "Granted scope strings", items_type: "string" },
    status: { type: "enum", description: "Lifecycle status (universal across all kinds)", required: true, enum_values: ["active", "revoked"] },
    granted_at: { type: "datetime", description: "When the grant was approved", required: true },
    last_used_at: { type: "datetime", description: "Most recent successful use of any token issued under this grant" },
    revoked_at: { type: "datetime", description: "When the grant was revoked, if any" },
    integration_ref: { type: "string", description: "For kind: integration — id of the Integration manifest this connection implements" },
    credential_ref: { type: "string", description: "For kind: integration — id of a system.credential item holding the integration's API key" },
    configuration: { type: "object", description: "For kind: integration — per-Integration JSON config payload (shape determined by the Integration manifest)" },
    direction: { type: "enum", description: "For kind: integration — does this integration read from, write to, or both", enum_values: ["read", "write", "both"] },
    triggers: { type: "array", description: "For kind: integration — array of trigger declarations. Each entry shape: { type: 'schedule' | 'webhook' | 'item-event' | 'manual', ...per-type config }. The Integration manifest constrains which trigger types are valid.", items_type: "object" },
    attached_device: { type: "string", description: "For kind: integration — id of a system.device item; set when the integration runs on a specific local device (e.g. a sync agent host)" },
    runtime_status: { type: "enum", description: "For kind: integration — operational health, distinct from the universal lifecycle `status`. Server-stamped only (the runtime executor is the legitimate writer; there is no client write surface).", enum_values: ["healthy", "degraded", "failing", "paused", "reauth_required"] },
    last_sync_at: { type: "datetime", description: "For kind: integration — last successful sync run timestamp" },
    next_run_at: { type: "datetime", description: "For kind: integration — next scheduled run, when applicable" },
    last_error_at: { type: "datetime", description: "For kind: integration — most recent failure timestamp (cleared on next success)" },
    feed_activity: { type: "boolean", description: "For kind: integration — when true, system.activity items emitted by this integration are server-stamped tier:'feed' (otherwise tier is omitted, as for all other system.* writes)" },
  },
};

const systemCredential: TypeSchema = {
  id: "system.credential",
  label: "Credential",
  description: "An API key or OAuth approval. Surfaces a Credentials list; carries permissions and last-used time; revocable. Lifecycle is bounded to active/revoked. Has no tier. For kind: oauth_token, the connector's OAuth provider config (upstream URLs, client id) is stored under `oauth_provider_config` and the client secret under `secret_encrypted` (AES-256-GCM via the connectionOauthToken HKDF domain). For kind: api_token, the upstream API base URL is stored under `api_token_config.upstream_base_url` and the user-supplied bearer token under `secret_encrypted` (same HKDF domain — no separate key minting). The companion connection items reference credentials via `credential_ref`.",
  version: 1,
  fields: {
    label: { type: "string", description: "Human-readable label", required: true },
    kind: { type: "enum", description: "Credential kind", required: true, enum_values: ["api_key", "oauth_token", "api_token"] },
    scopes: { type: "array", description: "Granted scope strings", items_type: "string" },
    last_used_at: { type: "datetime", description: "Most recent use timestamp" },
    oauth_provider_config: { type: "object", description: "For kind: oauth_token — non-secret OAuth provider config: { upstream_base_url, oauth_token_url, oauth_client_id }. The secret companion lives under `secret_encrypted`." },
    api_token_config: { type: "object", description: "For kind: api_token — non-secret upstream API config: { upstream_base_url, auth_scheme? }. `auth_scheme` is the HTTP Authorization scheme used to present the token; one of `Bearer` | `Token` | `Basic`, default `Bearer`. Readwise's REST API requires `Token <key>`; most others accept `Bearer`. The user-supplied secret lives under `secret_encrypted`." },
    secret_encrypted: { type: "string", description: "For kind: oauth_token — AES-256-GCM-encrypted client secret. For kind: api_token — AES-256-GCM-encrypted bearer token. Both encoded as base64-iv|base64-ciphertext|base64-tag, keyed via HKDF on the `connectionOauthToken` domain. Decrypted server-side only." },
  },
};

const systemDevice: TypeSchema = {
  id: "system.device",
  label: "Device",
  description: "A connected device — phone, laptop, watch, sync agent. Surfaces a Devices list in the console; carries a name, kind, and last-active timestamp; revocable. Lifecycle is bounded to active/revoked. Has no tier — the curated/feed dimension does not apply.",
  version: 1,
  fields: {
    name: { type: "string", description: "Display name (e.g. \"Aug's MacBook Pro\")", required: true },
    kind: { type: "enum", description: "Device class", required: true, enum_values: ["phone", "tablet", "laptop", "desktop", "watch", "sync-agent", "other"] },
    last_active_at: { type: "datetime", description: "Most recent activity timestamp" },
  },
};

const systemIntegration: TypeSchema = {
  id: "system.integration",
  label: "Integration",
  description: "A registered Integration release — the persisted form of an Integration manifest. One item per (publisher.name, version) pair: subsequent releases of the same Integration land as sibling items, not in-place updates, so a Connection installed against v1.0 keeps pointing at the manifest it was installed with even after v1.1 lands. The `manifest` field carries the full validated IntegrationManifest blob the install pipeline persists; `manifest_name`, `manifest_version`, `publisher`, and `direction` are denormalized onto the item for cheap query/list. Installed at runtime via POST /integrations (platform credential gated). system.connection.integration references the item id via integration_ref.",
  version: 1,
  fields: {
    manifest_name: { type: "string", description: "Publisher-namespaced manifest name, e.g. `acme.calendar-sync`. Together with `manifest_version` identifies a unique installable release.", required: true },
    manifest_version: { type: "string", description: "Semver of this Integration release (e.g. `1.0.3`). Distinct from `manifest_schema_version` (which is the contract version of the manifest format itself).", required: true },
    publisher: { type: "string", description: "Human-readable publisher name (e.g. `Acme Inc.`). Carried over from manifest.publisher for list-view display.", required: true },
    summary: { type: "string", description: "Short Integration description from the manifest, surfaced on the install consent screen." },
    direction: { type: "enum", description: "Read/write direction declared by the manifest. Drives consent-screen wording.", enum_values: ["read", "write", "both"] },
    runtime_compatibility: { type: "array", description: "Manifest's declared runtime compatibility (subset of `hosted | self-hosted | local`). Determines which Worker tier the install pipeline targets.", items_type: "string" },
    manifest: { type: "object", description: "Full validated IntegrationManifest blob. Immutable for the lifetime of this item — new releases register as siblings.", required: true },
    registered_at: { type: "datetime", description: "When the manifest was registered with the server (POST /integrations).", required: true },
  },
};

